ALTER TABLE ci_runs DROP CONSTRAINT ci_runs_trigger_check;
ALTER TABLE ci_runs ADD CONSTRAINT ci_runs_trigger_check CHECK (trigger IN ('push','pull_request','manual','scheduled'));
ALTER TABLE ci_runs ADD COLUMN repository_snapshot jsonb;
ALTER TABLE ci_runs ADD COLUMN pull_request_number integer CHECK (pull_request_number > 0);
ALTER TABLE ci_runs ADD COLUMN event_action text;
CREATE TABLE delivery_policies (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), input jsonb NOT NULL, repository jsonb NOT NULL, hash text NOT NULL, revision integer NOT NULL DEFAULT 0 CHECK (revision >= 0), revoked_at timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE delivery_preparations (id uuid PRIMARY KEY, policy_id uuid NOT NULL REFERENCES delivery_policies(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), ci_run_id uuid NOT NULL REFERENCES ci_runs(id), intent text NOT NULL CHECK(intent IN ('build','release','rollback','cleanup')), commit_sha text NOT NULL CHECK(commit_sha ~ '^[a-f0-9]{40}$'), artifact_id uuid, deployment_id uuid, manifest jsonb NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE delivery_commands (plan_id uuid PRIMARY KEY REFERENCES execution_plans(id), preparation_id uuid NOT NULL REFERENCES delivery_preparations(id), epoch integer NOT NULL CHECK(epoch > 0), authority text NOT NULL CHECK(authority IN ('owner','policy')));
CREATE TABLE delivery_runs (id uuid PRIMARY KEY, preparation_id uuid NOT NULL REFERENCES delivery_preparations(id), run_id uuid NOT NULL UNIQUE REFERENCES execution_runs(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), intent text NOT NULL CHECK(intent IN ('build','release','rollback','cleanup')), state text NOT NULL CHECK(state IN ('reserved','building','built','staged','active','retired','released','unknown','quarantined')), artifact_id uuid, previous_deployment_id uuid, generation integer NOT NULL CHECK(generation > 0), evidence text, reason text, updated_at timestamptz NOT NULL);
CREATE TABLE delivery_artifacts (id uuid PRIMARY KEY, preparation_id uuid NOT NULL UNIQUE REFERENCES delivery_preparations(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), metadata jsonb NOT NULL, provider_evidence jsonb NOT NULL);
CREATE TABLE delivery_targets (environment_id uuid PRIMARY KEY REFERENCES environments(id), active_deployment_id uuid REFERENCES delivery_runs(id), pending_run_id uuid REFERENCES execution_runs(id), generation integer NOT NULL DEFAULT 0 CHECK(generation >= 0));
CREATE TABLE delivery_steps (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES execution_runs(id), step text NOT NULL CHECK(step IN ('build','stage','readiness','promote','cleanup')), state text NOT NULL CHECK(state IN ('intended','observed')), scope_hash text NOT NULL, evidence text, created_at timestamptz NOT NULL);
CREATE UNIQUE INDEX delivery_step_run_key ON delivery_steps(run_id,step);
CREATE TABLE delivery_previews (id uuid PRIMARY KEY, policy_id uuid NOT NULL REFERENCES delivery_policies(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL UNIQUE REFERENCES environments(id), pull_request_number integer NOT NULL CHECK(pull_request_number > 0), state text NOT NULL CHECK(state IN ('prepared','active','cleanup-required','retired','unknown')), url text, expires_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
